using System;
using System.Text;
using UnityEngine;
using UnityEngine.InputSystem;
using UnityEngine.EventSystems;
using TMPro;
using DG.Tweening;
using LWS.TruckHockey;
using LWS.TruckSports;
namespace LWS.TruckWallball {
public enum WallballScreen {Setup,Join,Play,Pause,Help,Settings,Confirm,Disconnect,Result}
public sealed class WallballMenus:SportsMenuView {
 public WallballMatch match;public WallballScreen Screen;public TMP_InputField[] names;public TMP_Text[] sourceLabels,levelLabels,colorLabels;public TMP_Text setupControls,controlsText,modeLabel,joinText,disconnectText,scoreText,serveText,noticeText,resultText,confirmText;public GameObject hud;public RectTransform resultTitle;
 public Color[] palette={new Color(.15f,.8f,1),new Color(1,.55f,.13f),new Color(.85f,.25f,.7f),new Color(.6f,1,.3f),new Color(.9f,.85f,.25f)};
 int revision=-1,gateFrame;bool released;float nextHud;string pending;WallballScreen previous;SportsMenuAction[][] cached;Tween celebration;
 public const string Rules="ARCADE WALLBALL • FIRST TO 11, WIN BY TWO • RALLY SCORING.\n\nBoth trucks share the court and pass through each other. Drive and jump at any time in a rally. Only the named eligible truck can touch the ball. Eligibility changes never freeze movement; separate from an overlapping ball to arm a fresh physical contact.\n\nPhysically hit the ball into the highlighted front wall before it touches the floor. A legal wall contact makes the opponent eligible. Volley it, or return after one floor bounce; SECOND BOUNCE loses the rally. A floor contact before reaching the wall is MISSED WALL. Invalid wall contact or side/rear escape is OUT against the responsible hitter, even if the receiver declines an out ball. Every rally awards one point; the winner serves next.\n\nSERVE: drive from the marked service box into the reachable ball. You have 25 active serving seconds. Countdown/pause do not consume this time. The opening server alternates on rematches. Genuine simulation failures replay neutrally with unchanged score.\n\nKeyboard defaults: W/A/S/D + SPACE jump; arrows + RIGHT SHIFT jump. Whole pad: left stick steer, RT/LT drive/brake, SOUTH/A/Cross jump. Shared pad: LEFT STICK + LT jump; RIGHT STICK + RT jump. North joins. Esc/Start pauses. Actual assigned controls appear in setup/HUD. Reconnect/reassign requires release and fresh confirmation; confirmation never becomes a jump.\n\nThese are simplified arcade rules, not an official tournament ruleset.";
 protected override void Start(){base.Start();cached=new SportsMenuAction[pages.Length][];for(int i=0;i<pages.Length;i++)if(pages[i]!=null)cached[i]=pages[i].GetComponentsInChildren<SportsMenuAction>(true);for(int i=0;i<2;i++){int slot=i;names[i].onEndEdit.AddListener(v=>{match.players[slot].name=string.IsNullOrWhiteSpace(v)?"Player "+(slot+1):v.Trim();match.Save();match.Dirty();});}Show(Screen);}
 public void Gate(){gateFrame=Time.frameCount;released=false;}public void Dirty(){revision=-1;}
 public void Show(WallballScreen screen){Screen=screen;hud.SetActive(screen==WallballScreen.Play);base.Show((int)screen);Gate();Dirty();if(screen==WallballScreen.Result)resultText.text=match.players[match.rules.Winner].name+" WINS\n"+match.players[0].name+"  "+match.rules.Score[0]+" : "+match.rules.Score[1]+"  "+match.players[1].name+"\nFirst to 11 • Win by two • Rematch alternates opening serve";}
 bool FreshConfirm(){if(!released)return false;if(SportsDeviceInput.KeyDown(Key.Enter)||SportsDeviceInput.KeyDown(Key.Space)||Mouse.current!=null&&Mouse.current.leftButton.wasReleasedThisFrame)return true;foreach(var p in match.players)if(p.controller&&p.pad!=null&&p.pad.added&&p.pad.enabled&&p.pad.buttonSouth.wasPressedThisFrame)return true;return match.AllAI;}
 public override void Action(string key){

if((Screen==WallballScreen.Disconnect||Screen==WallballScreen.Join||Screen==WallballScreen.Confirm||Screen==WallballScreen.Pause||key=="rematch")&&!FreshConfirm())return;base.Action(key);if(key.StartsWith("source")){match.CycleSource(int.Parse(key.Substring(6)));return;}if(key.StartsWith("level")){int i=int.Parse(key.Substring(5));match.players[i].difficulty=(HockeyDifficulty)(((int)match.players[i].difficulty+1)%3);match.Save();match.Dirty();return;}if(key.StartsWith("color")){int i=int.Parse(key.Substring(5)),c=Array.IndexOf(palette,match.players[i].color);c=(c+1)%palette.Length;if(palette[c]==match.players[1-i].color)c=(c+1)%palette.Length;match.players[i].color=palette[c];match.Save();match.Dirty();return;}if(key.StartsWith("reassign")){match.Unassign(int.Parse(key.Substring(8)));return;}
  switch(key){case "mode":match.Configure((WallballMode)(((int)match.mode+1)%6));break;case "start":match.StartMatch();break;case "resume":match.Resume();break;case "rematch":match.StartMatch(true);break;case "setup":match.ChangeSetup();break;case "help":previous=Screen;Show(WallballScreen.Help);break;case "settings":previous=Screen;SettingsText();Show(WallballScreen.Settings);break;case "back":Back();break;case "front":if(match.InMatch&&match.rules.Phase!=WallballPhase.Finished){pending="front";confirmText.text="RETURN TO SPORT SELECTION?\nThe current match will be abandoned.";Show(WallballScreen.Confirm);}else SportsNavigation.FrontEnd();break;case "restart":pending="restart";confirmText.text="RESTART MATCH?\nScores reset; participant setup is retained.";Show(WallballScreen.Confirm);break;case "yes":if(pending=="restart")match.StartMatch();else SportsNavigation.FrontEnd();break;case "no":Show(WallballScreen.Pause);break;}}
 public void Back(){if((Screen==WallballScreen.Confirm||Screen==WallballScreen.Disconnect||Screen==WallballScreen.Pause)&&!released)return;if(Screen==WallballScreen.Play){match.Pause();return;}if(Screen==WallballScreen.Pause||Screen==WallballScreen.Disconnect){if(released)match.Resume();return;}if(Screen==WallballScreen.Help||Screen==WallballScreen.Settings)Show(previous);else if(Screen==WallballScreen.Confirm)Show(WallballScreen.Pause);else if(Screen==WallballScreen.Join)match.ChangeSetup();else if(Screen==WallballScreen.Setup)SportsNavigation.FrontEnd();}
 void Refresh(){if(cached==null||revision==match.Revision)return;revision=match.Revision;modeLabel.text=new[]{"HUMAN vs AI","SHARED KEYBOARD","SEPARATE CONTROLLERS","KEYBOARD + CONTROLLER","AI vs AI • SPECTATE","ONE PAD • TWO STICKS","CUSTOM MIX"}[(int)match.mode];var text=new StringBuilder("North / Y / Triangle joins an empty input source.\n\n");for(int i=0;i<2;i++){var p=match.players[i];names[i].SetTextWithoutNotify(p.name);sourceLabels[i].text=p.source.ToString().ToUpper();levelLabels[i].text=p.difficulty.ToString().ToUpper();levelLabels[i].transform.parent.gameObject.SetActive(p.source==HockeySource.AI);colorLabels[i].text="COLOR";colorLabels[i].color=p.color;text.Append(match.Controls(i)).Append(" • ").Append(p.name).Append(" • ").Append(p.source).Append(p.controller?(match.Ready(i)?" • "+p.pad.displayName:" • DISCONNECTED / NOT JOINED"):"").Append('\n');}text.Append("\n").Append(match.ValidateOwnership(out string reason)?"Whole pad = one participant; left/right sticks = separate owners.\nScore, rally, velocities and both shared owners are preserved on disconnect.":reason);joinText.text=disconnectText.text=text.ToString();setupControls.text=match.players[0].name+": "+match.Controls(0)+"\n"+match.players[1].name+": "+match.Controls(1);foreach(int page in new[]{1,7})foreach(var a in cached[page]){if(a.action.StartsWith("reassign"))a.gameObject.SetActive(match.players[int.Parse(a.action.Substring(8))].controller);if(a.action=="resume"||a.action=="start"){a.button.isInteractable=match.DevicesReady;a.GetComponent<UnityEngine.UI.Button>().interactable=match.DevicesReady;}}Focus();SelectPrimary();}
 void SelectPrimary(){if((Screen!=WallballScreen.Join&&Screen!=WallballScreen.Disconnect)||!match.DevicesReady||cached==null||EventSystem.current==null)return;foreach(var a in cached[(int)Screen])if(a.action==(Screen==WallballScreen.Join?"start":"resume")){EventSystem.current.SetSelectedGameObject(a.gameObject);break;}}
 protected override void Update(){base.Update();if(!released&&Time.frameCount>gateFrame){bool neutral=!SportsDeviceInput.KeyHeld(Key.Enter)&&!SportsDeviceInput.KeyHeld(Key.Space)&&(Mouse.current==null||!Mouse.current.leftButton.isPressed&&!Mouse.current.leftButton.wasReleasedThisFrame);for(int i=0;i<2;i++)if(match.Ready(i))neutral&=match.Neutral(i);foreach(var pad in Gamepad.all)neutral&=!pad.buttonSouth.isPressed;if(neutral){released=true;SelectPrimary();}}Refresh();foreach(var pad in Gamepad.all)if(menuInput.Down(pad,8)&&Screen!=WallballScreen.Play){Back();break;}if(Time.unscaledTime<nextHud)return;nextHud=Time.unscaledTime+.1f;if(Screen==WallballScreen.Play){scoreText.text="<color=#"+ColorUtility.ToHtmlStringRGB(match.players[0].color)+">"+match.players[0].name+"  "+match.rules.Score[0]+"</color>   :   <color=#"+ColorUtility.ToHtmlStringRGB(match.players[1].color)+">"+match.rules.Score[1]+"  "+match.players[1].name+"</color>";serveText.text="SERVER: "+match.players[match.rules.Server].name+"\n"+(match.rules.Phase==WallballPhase.Serving?"TO SERVE • "+Mathf.CeilToInt(match.rules.Timer)+"s":match.rules.Phase==WallballPhase.Countdown?"COUNTDOWN "+Mathf.CeilToInt(match.rules.Timer):match.rules.Eligible>=0?match.players[match.rules.Eligible].name+" TO HIT"+(!match.Armed[match.rules.Eligible]?" • SEPARATE TO ARM":"")+(match.rules.Bounces==1?" • FIRST BOUNCE":""):match.rules.Phase==WallballPhase.Outgoing?match.players[match.rules.Hitter].name+" TO WALL":"POINT");noticeText.text=match.Notice;controlsText.text=match.players[0].name+": "+match.Controls(0)+"\n"+match.players[1].name+": "+match.Controls(1);}}
 public void Celebrate(){celebration?.Kill();resultTitle.localScale=Vector3.one;celebration=resultTitle.DOScale(1.06f,.18f).SetLoops(2,LoopType.Yoyo).SetUpdate(true);foreach(var p in match.players)if(p.controller&&p==match.players[match.rules.Winner])feedback.Pulse(p.pad,.2f,.2f);}
 void OnDisable(){celebration?.Kill();}
}
}
